    base = mix(base, vec3(0.48, 0.3, 0.2), smoothstep(0.55, 0.8, fine) * 0.4);
    base = mix(base, vec3(0.5, 0.56, 0.62), smoothstep(0.6, 0.92, abs(lat)));
