    paveC *= 0.94 + 0.08 * th21(floor(vTW.xz * 40.0));
    paveC = mix(paveC, s2l(vec3(0.46, 0.38, 0.32)), hp.x * 0.45);
    paveC = mix(paveC, s2l(vec3(0.52, 0.41, 0.33)), smoothstep(0.55, 0.9, nzC.g) * 0.3);
